INSERT INTO `el_mng_runtime_receipt` (`run_id`, `paper_id`, `exam_id`, `participant_type`, `participant_id`, `submit_type`, `started_at`, `limit_time`, `submitted_at`, `user_time_seconds`) VALUES ('dceabcbd-44bb-476c-920a-6958191027a2','e205a659-9bde-494c-ad75-2b37a13fc791','9051103000000000501','candidate','77029ad0-3cd4-4b76-8016-b3da2df73060','manual','2026-10-08 23:38:06.000000','2026-10-09 00:03:06.000000','2026-10-08 23:38:38.000000',32);
INSERT INTO `el_mng_report_revision` (`id`, `run_id`, `paper_id`, `exam_id`, `revision`, `mode`, `test_title`, `test_label`, `content_version`, `content_sha`, `template_version`, `template_sha`, `data_snapshot`, `data_sha`, `file_key`, `file_sha`, `file_bytes`, `created_by`, `created_at`) VALUES ('910dc08e-fcc1-464c-b755-9626438fb9ab','56caced4-55c1-4630-bd7e-dc193abac33c','3b9532ab-db61-473e-b16c-fab701ee7cdb','9051103000000000502',1,'test','管理特质 TEST 测试报告','仅供系统测试，不可作为人才决策依据','mng-customer-text-test-v1','b0498249ae057e3aa1b798922ed2d53a6ca304811943b3b41f4f64f9b024e84c','mng-test-lo-template-v2','05c55e77e567c6111ba62c08f2e69b4d5e5b416b2dd989c49914cc95b962a84c','{\"schema\":\"mng-test-report-data-v1\",\"testOnly\":true,\"runId\":\"56caced4-55c1-4630-bd7e-dc193abac33c\",\"paperId\":\"3b9532ab-db61-473e-b16c-fab701ee7cdb\",\"examId\":\"9051103000000000502\",\"questionnaire\":\"leader\",\"versions\":{\"product\":\"mng-00502-v1\",\"question\":\"mng-00502-db-current-v1\",\"scoring\":\"mng-percent-scoring-v1\",\"norm\":\"mng-norm-20260928-v1\"},\"inputSha\":\"41bfc3ff6f14d8d04567e5fd2e2d425ede2072b5bb4ef0a7e00a458de5ae0dd5\",\"contentSourceSha\":\"b0498249ae057e3aa1b798922ed2d53a6ca304811943b3b41f4f64f9b024e84c\",\"participant\":{\"name\":\"TEST00502-c51130cb\",\"gender\":\"1\",\"telephone\":\"18851130002\",\"affiliation\":\"\",\"post\":\"\"},\"submittedAt\":\"2026-10-08 23:39\",\"overall\":{\"score\":\"50.00\",\"level\":\"合格管理者\",\"diagnosis\":\"管理表现中规中矩，与大多数管理者处于同一水平线。能完成日常管理职责，但在关键管理行为上尚未形成稳定优势。部分领域存在短板，需要借助培训和实战积累来挖掘自身潜力。\",\"advice\":[\"受测者已能完成日常管理职责，可针对岗位最需要的一两项技能开展训练（如沟通反馈、目标分解、时间管理），以在岗任务为载体，不必另设培训项目。\",\"可为受测者指定一名资深管理者作为带教人，每月至少开展一次现场指导或共同复盘，重点解决具体管理场景中的实际问题。\",\"结合维度得分确定一个优先提升的维度，设定可衡量的阶段性目标（如季度内完成某项流程改进），季度末评估一次，避免同时铺开多项改进。\"],\"chartScore\":\"50.000000000000\"},\"dimensions\":[{\"key\":\"self_confidence\",\"name\":\"自信心\",\"score\":\"50.00\",\"norm\":\"57.50\",\"level\":\"合格\",\"diagnosis\":\"相信自己有应对问题的能力，遇到挫折并不畏缩，敢于迎接挑战，对自己有信心。\",\"advice\":\"受测者已具备基本信心，可在关键场合争取公开表达的机会，事前共同梳理方案与备选方案，事后给予肯定；遇到挫折时上级以具体事实反馈，帮助保持状态。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"57.500000000000\"},{\"key\":\"emotional_stability\",\"name\":\"情绪稳定性\",\"score\":\"50.00\",\"norm\":\"55.00\",\"level\":\"合格\",\"diagnosis\":\"在大多数情况下能够保持冷静和理性，有效地进行情绪调节和管理，但在某些特定情境下可能会出现情绪波动。\",\"advice\":\"受测者可承担有一定时限压力的任务，高难度沟通前由上级提前通报情况并统一口径；可教授“觉察—抽离—复述”的情绪处理方式，每月选取一次实际案例共同复盘。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"55.000000000000\"},{\"key\":\"self_discipline\",\"name\":\"自律性\",\"score\":\"50.00\",\"norm\":\"56.25\",\"level\":\"合格\",\"diagnosis\":\"具有一定的自我约束和自我调整的能力，能够适应不断变化的工作环境，有效应对各种挑战和困难。\",\"advice\":\"受测者已具备基本自律，可通过制度与检查进一步稳定产出；任务拆分为两周以内的小节点，进度在部门内公开，上级每周检查一次。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"56.250000000000\"},{\"key\":\"sociality\",\"name\":\"社会性\",\"score\":\"50.00\",\"norm\":\"51.25\",\"level\":\"合格\",\"diagnosis\":\"社交能力中等，能够自如地与他人交流，但与陌生人初交往时略有些拘谨，相处一段时间后才表现放松。\",\"advice\":\"受测者可承担新人引导、跨部门走访、外部对接等需要接触陌生对象的工作；事先提供话题清单和背景资料，事后由上级了解进展并给予反馈，帮助逐步适应。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"51.250000000000\"},{\"key\":\"leadership\",\"name\":\"领导性\",\"score\":\"50.00\",\"norm\":\"52.50\",\"level\":\"合格\",\"diagnosis\":\"有一定的领导能力，面对问题能够坚持自己的见解，可以独立处理日常工作，但不将自己的观点、看法强加于他人。\",\"advice\":\"受测者已能独立处理日常工作，可再给一些牵头机会，如主持一次复盘、牵头一项专项改进；在会议中主动点名征求意见，并要求以“我的建议是……理由是……”的方式表达，养成先出方案的习惯。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"52.500000000000\"},{\"key\":\"interpersonal_sensitivity\",\"name\":\"人际敏感性\",\"score\":\"50.00\",\"norm\":\"50.00\",\"level\":\"合格\",\"diagnosis\":\"能够有意识地关注他人的言行，了解对方的需要，体察他人的动机和态度，做到举止有度。\",\"advice\":\"受测者可参与面谈、协调会等需要观察对方反应的场合；事前共同梳理对方最关注的三件事，事后由本人复述对方的态度信号、上级补充校正，每月选取一次沟通进行复盘。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"50.000000000000\"},{\"key\":\"cooperation\",\"name\":\"合作性\",\"score\":\"50.00\",\"norm\":\"57.50\",\"level\":\"合格\",\"diagnosis\":\"与他人合作的过程中，主动性和积极性一般，对团队整体目标的理解有时会不够深入。\",\"advice\":\"受测者承担任务时需明确应同步的关联岗位，每周至少与一至两个关联岗位同步信息或提供一次支持；在团队目标讨论时要求站在整体角度提出建议，把关注点从个人任务转向团队效率。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"57.500000000000\"},{\"key\":\"planning\",\"name\":\"计划性\",\"score\":\"50.00\",\"norm\":\"53.75\",\"level\":\"合格\",\"diagnosis\":\"做事有计划、有条理，会预先对自己的工作和生活作出一定的安排，但也有一定的随机性。\",\"advice\":\"受测者已具备基本规划习惯，可借助统一模板进一步做实：每天列出不超过五项关键任务并排序，每周用十五分钟复盘并安排下一周；上级帮助识别最常占用时间的三类干扰并逐一隔离。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"53.750000000000\"},{\"key\":\"responsibility\",\"name\":\"责任心\",\"score\":\"50.00\",\"norm\":\"58.75\",\"level\":\"合格\",\"diagnosis\":\"有责任意识，也能主动帮助他人，能够有效完成自己的工作。\",\"advice\":\"受测者已具备责任意识，可在本职之外认领一件需负责到底的事项，如带教一名新人、梳理一条流程；要求建立闭环台账，做到事事有回音、件件有落实，上级定期检查。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"58.750000000000\"},{\"key\":\"decisiveness\",\"name\":\"决断性\",\"score\":\"50.00\",\"norm\":\"53.75\",\"level\":\"合格\",\"diagnosis\":\"在面对一般情境时，能够保持冷静和镇定，较为果断地做出决策。\",\"advice\":\"受测者负责的决策事项需设定截止时间，信息收集到点即要求形成决定；可把大决策拆分为若干可逆的小决策先试再推，出现犹豫时由上级及时定夺，通过实践降低对不确定性的顾虑。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"53.750000000000\"},{\"key\":\"proactiveness\",\"name\":\"进取性\",\"score\":\"50.00\",\"norm\":\"55.00\",\"level\":\"合格\",\"diagnosis\":\"具备一定的上进心，能够主动参与竞争，但不会付出特别多的努力去争取成功。\",\"advice\":\"受测者已有一定上进心，目标可设定略高于常规水平，并要求公开承诺；遇到卡点时上级帮助区分是能力困难还是资源不足，再向上争取支持，避免因一次挫败就降低要求。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"55.000000000000\"},{\"key\":\"learning\",\"name\":\"学习力\",\"score\":\"50.00\",\"norm\":\"53.75\",\"level\":\"合格\",\"diagnosis\":\"能够主动寻找学习资源并持续学习，但在面对挑战和困难时可能需要额外的支持。\",\"advice\":\"受测者已能主动学习，可安排学习伙伴或导师，每周固定三小时学习时间并纳入工作安排；难度较大的内容拆解为小模块逐步攻克，建立请教通道，遇到困难时及时提供支持。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"53.750000000000\"},{\"key\":\"innovation\",\"name\":\"创新性\",\"score\":\"50.00\",\"norm\":\"50.00\",\"level\":\"合格\",\"diagnosis\":\"对新鲜事物保持好奇，并在一定条件下能够提出新的工作思路和解决方案，使团队成员耳目一新。\",\"advice\":\"受测者对新事物已有好奇心，可要求每极度针对一个业务痛点提出一条改进方案并推动试行，年末复盘落地情况；安排参加跨界案例分享，接触前沿做法。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"50.000000000000\"}],\"modules\":[{\"Key\":\"self\",\"Score\":\"50.00\",\"ChartScore\":\"50.000000000000\"},{\"Key\":\"interpersonal\",\"Score\":\"50.00\",\"ChartScore\":\"50.000000000000\"},{\"Key\":\"task\",\"Score\":\"50.00\",\"ChartScore\":\"50.000000000000\"},{\"Key\":\"development\",\"Score\":\"50.00\",\"ChartScore\":\"50.000000000000\"}],\"highest\":[{\"Key\":\"self_confidence\",\"Name\":\"自信心\",\"Text\":\"相信能应对问题，遇挫不退缩，敢于迎接挑战。\"},{\"Key\":\"emotional_stability\",\"Name\":\"情绪稳定性\",\"Text\":\"多数时候能冷静并有效调节，偶有情绪波动。\"},{\"Key\":\"self_discipline\",\"Name\":\"自律性\",\"Text\":\"有一定自律性，能适应变化、有效应对挑战。\"}],\"lowest\":[{\"Key\":\"self_confidence\",\"Name\":\"自信心\",\"Text\":\"相信能应对问题，遇挫不退缩，敢于迎接挑战。\"},{\"Key\":\"emotional_stability\",\"Name\":\"情绪稳定性\",\"Text\":\"多数时候能冷静并有效调节，偶有情绪波动。\"},{\"Key\":\"self_discipline\",\"Name\":\"自律性\",\"Text\":\"有一定自律性，能适应变化、有效应对挑战。\"}]}','10bf4c3a8be76eb76d53fdb30709f2f9d42855cd16ca2295628e29a8f3955742','910dc08e-fcc1-464c-b755-9626438fb9ab.pdf','b392cff6d3b63b44e7304927e78f27121f1dce63682494caf8cafb703d0bfc5c',648159,1,'2026-10-08 23:39:21.723893');
INSERT INTO `el_mng_report_revision` (`id`, `run_id`, `paper_id`, `exam_id`, `revision`, `mode`, `test_title`, `test_label`, `content_version`, `content_sha`, `template_version`, `template_sha`, `data_snapshot`, `data_sha`, `file_key`, `file_sha`, `file_bytes`, `created_by`, `created_at`) VALUES ('fffa814c-49ac-4f5f-8ede-f8493bed1055','dceabcbd-44bb-476c-920a-6958191027a2','e205a659-9bde-494c-ad75-2b37a13fc791','9051103000000000501',1,'test','管理特质 TEST 测试报告','仅供系统测试，不可作为人才决策依据','mng-customer-text-test-v1','b0498249ae057e3aa1b798922ed2d53a6ca304811943b3b41f4f64f9b024e84c','mng-test-lo-template-v2','05c55e77e567c6111ba62c08f2e69b4d5e5b416b2dd989c49914cc95b962a84c','{\"schema\":\"mng-test-report-data-v1\",\"testOnly\":true,\"runId\":\"dceabcbd-44bb-476c-920a-6958191027a2\",\"paperId\":\"e205a659-9bde-494c-ad75-2b37a13fc791\",\"examId\":\"9051103000000000501\",\"questionnaire\":\"staff\",\"versions\":{\"product\":\"mng-00501-v1\",\"question\":\"mng-00501-db-current-v1\",\"scoring\":\"mng-percent-scoring-v1\",\"norm\":\"mng-norm-20260928-v1\"},\"inputSha\":\"8c17190bf859c56da057a7d8f6b250b267124dd342db14cb277cc4c163007469\",\"contentSourceSha\":\"b0498249ae057e3aa1b798922ed2d53a6ca304811943b3b41f4f64f9b024e84c\",\"participant\":{\"name\":\"TEST00501-c51130cb\",\"gender\":\"0\",\"telephone\":\"18851130001\",\"affiliation\":\"\",\"post\":\"\"},\"submittedAt\":\"2026-10-08 23:38\",\"overall\":{\"score\":\"50.00\",\"level\":\"合格管理者\",\"diagnosis\":\"管理表现中规中矩，与大多数管理者处于同一水平线。能完成日常管理职责，但在关键管理行为上尚未形成稳定优势。部分领域存在短板，需要借助培训和实战积累来挖掘自身潜力。\",\"advice\":[\"受测者已能完成日常管理职责，可针对岗位最需要的一两项技能开展训练（如沟通反馈、目标分解、时间管理），以在岗任务为载体，不必另设培训项目。\",\"可为受测者指定一名资深管理者作为带教人，每月至少开展一次现场指导或共同复盘，重点解决具体管理场景中的实际问题。\",\"结合维度得分确定一个优先提升的维度，设定可衡量的阶段性目标（如季度内完成某项流程改进），季度末评估一次，避免同时铺开多项改进。\"],\"chartScore\":\"50.000000000000\"},\"dimensions\":[{\"key\":\"self_confidence\",\"name\":\"自信心\",\"score\":\"50.00\",\"norm\":\"57.50\",\"level\":\"合格\",\"diagnosis\":\"相信自己有应对问题的能力，遇到挫折并不畏缩，敢于迎接挑战，对自己有信心。\",\"advice\":\"受测者已具备基本信心，可在关键场合争取公开表达的机会，事前共同梳理方案与备选方案，事后给予肯定；遇到挫折时上级以具体事实反馈，帮助保持状态。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"57.500000000000\"},{\"key\":\"emotional_stability\",\"name\":\"情绪稳定性\",\"score\":\"50.00\",\"norm\":\"55.00\",\"level\":\"合格\",\"diagnosis\":\"在大多数情况下能够保持冷静和理性，有效地进行情绪调节和管理，但在某些特定情境下可能会出现情绪波动。\",\"advice\":\"受测者可承担有一定时限压力的任务，高难度沟通前由上级提前通报情况并统一口径；可教授“觉察—抽离—复述”的情绪处理方式，每月选取一次实际案例共同复盘。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"55.000000000000\"},{\"key\":\"self_discipline\",\"name\":\"自律性\",\"score\":\"50.00\",\"norm\":\"56.25\",\"level\":\"合格\",\"diagnosis\":\"具有一定的自我约束和自我调整的能力，能够适应不断变化的工作环境，有效应对各种挑战和困难。\",\"advice\":\"受测者已具备基本自律，可通过制度与检查进一步稳定产出；任务拆分为两周以内的小节点，进度在部门内公开，上级每周检查一次。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"56.250000000000\"},{\"key\":\"sociality\",\"name\":\"社会性\",\"score\":\"50.00\",\"norm\":\"51.25\",\"level\":\"合格\",\"diagnosis\":\"社交能力中等，能够自如地与他人交流，但与陌生人初交往时略有些拘谨，相处一段时间后才表现放松。\",\"advice\":\"受测者可承担新人引导、跨部门走访、外部对接等需要接触陌生对象的工作；事先提供话题清单和背景资料，事后由上级了解进展并给予反馈，帮助逐步适应。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"51.250000000000\"},{\"key\":\"leadership\",\"name\":\"领导性\",\"score\":\"50.00\",\"norm\":\"52.50\",\"level\":\"合格\",\"diagnosis\":\"有一定的领导能力，面对问题能够坚持自己的见解，可以独立处理日常工作，但不将自己的观点、看法强加于他人。\",\"advice\":\"受测者已能独立处理日常工作，可再给一些牵头机会，如主持一次复盘、牵头一项专项改进；在会议中主动点名征求意见，并要求以“我的建议是……理由是……”的方式表达，养成先出方案的习惯。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"52.500000000000\"},{\"key\":\"interpersonal_sensitivity\",\"name\":\"人际敏感性\",\"score\":\"50.00\",\"norm\":\"50.00\",\"level\":\"合格\",\"diagnosis\":\"能够有意识地关注他人的言行，了解对方的需要，体察他人的动机和态度，做到举止有度。\",\"advice\":\"受测者可参与面谈、协调会等需要观察对方反应的场合；事前共同梳理对方最关注的三件事，事后由本人复述对方的态度信号、上级补充校正，每月选取一次沟通进行复盘。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"50.000000000000\"},{\"key\":\"cooperation\",\"name\":\"合作性\",\"score\":\"50.00\",\"norm\":\"57.50\",\"level\":\"合格\",\"diagnosis\":\"与他人合作的过程中，主动性和积极性一般，对团队整体目标的理解有时会不够深入。\",\"advice\":\"受测者承担任务时需明确应同步的关联岗位，每周至少与一至两个关联岗位同步信息或提供一次支持；在团队目标讨论时要求站在整体角度提出建议，把关注点从个人任务转向团队效率。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"57.500000000000\"},{\"key\":\"planning\",\"name\":\"计划性\",\"score\":\"50.00\",\"norm\":\"53.75\",\"level\":\"合格\",\"diagnosis\":\"做事有计划、有条理，会预先对自己的工作和生活作出一定的安排，但也有一定的随机性。\",\"advice\":\"受测者已具备基本规划习惯，可借助统一模板进一步做实：每天列出不超过五项关键任务并排序，每周用十五分钟复盘并安排下一周；上级帮助识别最常占用时间的三类干扰并逐一隔离。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"53.750000000000\"},{\"key\":\"responsibility\",\"name\":\"责任心\",\"score\":\"50.00\",\"norm\":\"58.75\",\"level\":\"合格\",\"diagnosis\":\"有责任意识，也能主动帮助他人，能够有效完成自己的工作。\",\"advice\":\"受测者已具备责任意识，可在本职之外认领一件需负责到底的事项，如带教一名新人、梳理一条流程；要求建立闭环台账，做到事事有回音、件件有落实，上级定期检查。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"58.750000000000\"},{\"key\":\"decisiveness\",\"name\":\"决断性\",\"score\":\"50.00\",\"norm\":\"53.75\",\"level\":\"合格\",\"diagnosis\":\"在面对一般情境时，能够保持冷静和镇定，较为果断地做出决策。\",\"advice\":\"受测者负责的决策事项需设定截止时间，信息收集到点即要求形成决定；可把大决策拆分为若干可逆的小决策先试再推，出现犹豫时由上级及时定夺，通过实践降低对不确定性的顾虑。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"53.750000000000\"},{\"key\":\"proactiveness\",\"name\":\"进取性\",\"score\":\"50.00\",\"norm\":\"55.00\",\"level\":\"合格\",\"diagnosis\":\"具备一定的上进心，能够主动参与竞争，但不会付出特别多的努力去争取成功。\",\"advice\":\"受测者已有一定上进心，目标可设定略高于常规水平，并要求公开承诺；遇到卡点时上级帮助区分是能力困难还是资源不足，再向上争取支持，避免因一次挫败就降低要求。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"55.000000000000\"},{\"key\":\"learning\",\"name\":\"学习力\",\"score\":\"50.00\",\"norm\":\"53.75\",\"level\":\"合格\",\"diagnosis\":\"能够主动寻找学习资源并持续学习，但在面对挑战和困难时可能需要额外的支持。\",\"advice\":\"受测者已能主动学习，可安排学习伙伴或导师，每周固定三小时学习时间并纳入工作安排；难度较大的内容拆解为小模块逐步攻克，建立请教通道，遇到困难时及时提供支持。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"53.750000000000\"},{\"key\":\"innovation\",\"name\":\"创新性\",\"score\":\"50.00\",\"norm\":\"50.00\",\"level\":\"合格\",\"diagnosis\":\"对新鲜事物保持好奇，并在一定条件下能够提出新的工作思路和解决方案，使团队成员耳目一新。\",\"advice\":\"受测者对新事物已有好奇心，可要求每极度针对一个业务痛点提出一条改进方案并推动试行，年末复盘落地情况；安排参加跨界案例分享，接触前沿做法。\",\"chartScore\":\"50.000000000000\",\"chartNorm\":\"50.000000000000\"}],\"modules\":[{\"Key\":\"self\",\"Score\":\"50.00\",\"ChartScore\":\"50.000000000000\"},{\"Key\":\"interpersonal\",\"Score\":\"50.00\",\"ChartScore\":\"50.000000000000\"},{\"Key\":\"task\",\"Score\":\"50.00\",\"ChartScore\":\"50.000000000000\"},{\"Key\":\"development\",\"Score\":\"50.00\",\"ChartScore\":\"50.000000000000\"}],\"highest\":[{\"Key\":\"self_confidence\",\"Name\":\"自信心\",\"Text\":\"相信能应对问题，遇挫不退缩，敢于迎接挑战。\"},{\"Key\":\"emotional_stability\",\"Name\":\"情绪稳定性\",\"Text\":\"多数时候能冷静并有效调节，偶有情绪波动。\"},{\"Key\":\"self_discipline\",\"Name\":\"自律性\",\"Text\":\"有一定自律性，能适应变化、有效应对挑战。\"}],\"lowest\":[{\"Key\":\"self_confidence\",\"Name\":\"自信心\",\"Text\":\"相信能应对问题，遇挫不退缩，敢于迎接挑战。\"},{\"Key\":\"emotional_stability\",\"Name\":\"情绪稳定性\",\"Text\":\"多数时候能冷静并有效调节，偶有情绪波动。\"},{\"Key\":\"self_discipline\",\"Name\":\"自律性\",\"Text\":\"有一定自律性，能适应变化、有效应对挑战。\"}]}','263340214f71421a113e43817bfcc5cd6f992eda0e98e9b420c5217209728639','fffa814c-49ac-4f5f-8ede-f8493bed1055.pdf','d7fd78bb8f571a1eaef8c0d5f14008c57f6e6a3cc02019a206c6c2ca63d6eb6e',647985,1,'2026-10-08 23:38:43.763666');
